import { THINKING_SECONDS } from './artwork.js';
import { createThinkingView } from './view.js';

const INTERRUPTS = new Set(['do', 'walk', 'move', 'drop', 'place', 'cue', 'talk', 'setScheme']);
// thoughtShown is a persistent preference, not evidence that a status bubble is active.
const BLOCKING_STATES = ['dialogOpen', 'listening', 'thinking', 'status', 'stationary'];
const CLICK_MODES = new Set(['idle', 'look', 'sit', 'sleep', 'walk', 'run']);

/** Add random idle/click effects without requiring extra methods or vocabulary from an API 2 pack. */
export function withIdleThinking(body, host, options = {}) {
  const random = options.random ?? Math.random;
  const view = (options.createView ?? createThinkingView)(host);
  const delay = () => 20 + random() * 25;
  const states = {};
  let until = delay(), elapsed = null, hold = 0, disposed = false;
  let press = null, clicked = 0;

  function cancel() {
    elapsed = null;
    press = null;
    clicked = 0;
    until = delay();
    view.hide();
  }

  function available(layout) {
    return !disposed && hold <= 0 && !BLOCKING_STATES.some((key) => states[key])
      && !layout?.work && !layout?.ask && !layout?.recovering && !layout?.matterActivity;
  }

  function canThink(layout) {
    return available(layout) && layout?.mode === 'idle' && !layout.busy && !layout.pressing && !layout.moving;
  }

  function step(dt) {
    if (disposed) return;
    body.step(dt);
    if (!(dt > 0 && Number.isFinite(dt))) return;
    const delta = Math.min(dt, 1);
    if (press) press.age += delta;
    clicked = Math.max(0, clicked - delta);
    hold = Math.max(0, hold - delta);
    const layout = body.layout();
    if (!canThink(layout)) {
      if (elapsed !== null) cancel();
      return;
    }
    if (elapsed === null) {
      if (clicked > 0) { clicked = 0; until = 0; }
      until -= delta;
      if (until > 0) return;
      elapsed = 0;
      // Optional for custom bodies; the kit keeps this hold additive to existing holds.
      body.set?.({ hold: THINKING_SECONDS + 0.2 });
    }
    elapsed += delta;
    if (elapsed >= THINKING_SECONDS) cancel();
    else view.draw(elapsed, layout);
  }

  function set(state) {
    for (const key of BLOCKING_STATES) if (key in state) states[key] = state[key];
    if (Number.isFinite(state.hold)) hold = Math.max(hold, state.hold);
    if (hold > 0 || BLOCKING_STATES.some((key) => states[key]) || state.skin) cancel();
    return body.set?.(state);
  }

  function pointer(type, p) {
    const layout = body.layout();
    const eligible = type === 'down' && available(layout) && CLICK_MODES.has(layout.mode) && !layout.busy;
    const tap = press;
    const distance = tap ? Math.hypot(p?.x - tap.x, p?.y - tap.y) : Infinity;
    const age = Number.isFinite(p?.t) && Number.isFinite(tap?.t) ? (p.t - tap.t) / 1000 : tap?.age;
    const clickedBody = type === 'up' && tap && available(layout) && CLICK_MODES.has(layout.mode)
      && !layout.busy && distance <= 6 && age >= 0 && age < 0.4;
    // Preserve capture and drag bookkeeping, but ask the kit to skip its poke/jump reaction.
    if (type === 'down') cancel();
    else if (type !== 'move' || distance > 6) press = null;
    const result = body.pointer(type, type === 'up' ? { ...p, reaction: false } : p);
    if (eligible && body.layout().pressing) press = { x: p.x, y: p.y, t: p.t, age: 0 };
    if (clickedBody) clicked = 3;
    return result;
  }

  const overrides = {
    step, set,
    layout() {
      const layout = body.layout();
      return elapsed === null ? layout : { ...layout, moving: true };
    },
    dispose() {
      disposed = true;
      view.dispose();
      return body.dispose?.();
    },
  };
  if (typeof body.pointer === 'function') overrides.pointer = pointer;
  // Preserve optional methods, live getters, `this`, return values and the pack's own vocabulary.
  const bound = new Map();
  return new Proxy(body, {
    get(target, key) {
      if (Object.hasOwn(overrides, key)) return overrides[key];
      const value = Reflect.get(target, key, target);
      if (typeof value !== 'function') return value;
      if (!bound.has(key)) bound.set(key, (...args) => {
        if (INTERRUPTS.has(key)) cancel();
        return value.apply(target, args);
      });
      return bound.get(key);
    },
  });
}
